p="client/src/components/CompanyDocFolders.vue"
s=open(p,encoding="utf-8").read()
s=s.replace("  ownerType: { type: String, default: 'customer' },\n  ownerName: { type: String, default: '' },","  ownerType: { type: String, default: 'customer' },\n  ownerName: { type: String, default: '' },\n  billingTitle: { type: String, default: null },",1)
s=s.replace("const r = await fetchDocFolders(props.ownerType, props.ownerName)","const r = await fetchDocFolders(props.ownerType, props.ownerName, props.billingTitle)",1)
s=s.replace("const r = await fetchCompanyDocs(props.ownerType, props.ownerName, activeFolder.value.id)","const r = await fetchCompanyDocs(props.ownerType, props.ownerName, activeFolder.value.id, props.billingTitle)",1)
s=s.replace("const r = await createDocFolder(props.ownerType, props.ownerName, name)","const r = await createDocFolder(props.ownerType, props.ownerName, name, props.billingTitle || '')",1)
s=s.replace("      folderId: activeFolder.value.id,\n      files: list","      folderId: activeFolder.value.id,\n      billingTitle: props.billingTitle || '',\n      files: list",1)
s=s.replace("watch(() => props.ownerName, () => { closeFolder(); load() })","watch(() => props.ownerName, () => { closeFolder(); load() })\nwatch(() => props.billingTitle, () => { closeFolder(); load() })",1)
open(p,"w",encoding="utf-8",newline="").write(s)
print("component ok")
